import{_ as n,o,c as a,ag as e}from"./chunks/framework.B7PviQjB.js";const i="/docs/images/slides/animations-motion-panel.png",p=JSON.parse('{"title":"Add animations and transitions","description":"Add slide transitions and object animations to a deck, set their timing, and preview them in the editor.","frontmatter":{"title":"Add animations and transitions","description":"Add slide transitions and object animations to a deck, set their timing, and preview them in the editor.","type":"how-to"},"headers":[],"relativePath":"slides/animations.md","filePath":"slides/animations.md"}'),s={name:"slides/animations.md"};function r(l,t,d,g,h,m){return o(),a("div",null,[...t[0]||(t[0]=[e('<h1 id="add-animations-and-transitions" tabindex="-1">Add animations and transitions <a class="header-anchor" href="#add-animations-and-transitions" aria-label="Permalink to &quot;Add animations and transitions&quot;">​</a></h1><p>Add a transition that plays when a slide appears, and animations that bring objects onto a slide, take them off, or draw attention to them.</p><p>Transitions and animations play when you <a href="/docs/slides/present.html">present the deck</a>. Both are set in the <strong>Motion</strong> panel.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need edit access. A share-link viewer can&#39;t change motion.</li><li>On a phone, open the panel from <strong>More slide options</strong> (⋮) <strong>&gt; Motion…</strong>.</li></ul></div><h2 id="add-a-slide-transition" tabindex="-1">Add a slide transition <a class="header-anchor" href="#add-a-slide-transition" aria-label="Permalink to &quot;Add a slide transition&quot;">​</a></h2><ol><li>Open the slide.</li><li>Click <strong>Motion</strong> at the right end of the toolbar. The <strong>Motion</strong> panel opens.</li><li>Under <strong>Transition</strong>, choose a <strong>Type</strong>: <strong>Fade</strong>, <strong>Dissolve</strong>, <strong>Slide</strong>, <strong>Flip</strong>, <strong>Cube</strong>, <strong>Wipe</strong>, or <strong>Push</strong>.</li><li>Choose a <strong>Speed</strong>: <strong>Slow</strong>, <strong>Medium</strong>, or <strong>Fast</strong>.</li></ol><p>To use the same transition on every slide, click <strong>Apply to all slides</strong>. To remove a transition, set <strong>Type</strong> to <strong>None</strong>.</p><h2 id="animate-an-object" tabindex="-1">Animate an object <a class="header-anchor" href="#animate-an-object" aria-label="Permalink to &quot;Animate an object&quot;">​</a></h2><ol><li>Select the object on the slide.</li><li>In the <strong>Motion</strong> panel, under <strong>Animation</strong>, click <strong>+ Add animation</strong>. A new animation is added with <strong>Entrance</strong>, <strong>Fade In</strong>, and <strong>On Click</strong>.</li><li>Set <strong>Category</strong> and <strong>Effect</strong> (see <a href="#effects">Effects</a>).</li><li>Set <strong>Start</strong>: <ul><li><strong>On Click</strong> waits for the next click or key press.</li><li><strong>With Previous</strong> plays at the same time as the animation before it.</li><li><strong>After Previous</strong> plays when the animation before it ends.</li></ul></li><li>Adjust <strong>Duration</strong>, <strong>Delay</strong> (in milliseconds), and <strong>Easing</strong>.</li></ol><p>For <strong>Fly In</strong> and <strong>Fly Out</strong>, a <strong>Direction</strong> setting appears: <strong>From Top</strong>, <strong>From Bottom</strong>, <strong>From Left</strong>, or <strong>From Right</strong>. For a text box, select <strong>By paragraph</strong> to animate one paragraph at a time.</p><p><strong>+ Add animation</strong> is unavailable until you select an object.</p><p><img src="'+i+'" alt="Motion panel with a Fade transition and two animations, the second set to Fly In from the left"></p><h2 id="reorder-or-remove-animations" tabindex="-1">Reorder or remove animations <a class="header-anchor" href="#reorder-or-remove-animations" aria-label="Permalink to &quot;Reorder or remove animations&quot;">​</a></h2><p>Animations play in list order. On an animation in the list:</p><ul><li>Click <strong>Move up</strong> (↑) or <strong>Move down</strong> (↓) to change its place.</li><li>Click <strong>Remove animation</strong> (×) to delete it.</li></ul><h2 id="preview-animations" tabindex="-1">Preview animations <a class="header-anchor" href="#preview-animations" aria-label="Permalink to &quot;Preview animations&quot;">​</a></h2><p>Click <strong>Preview animations</strong> (▶) next to <strong>+ Add animation</strong>. The current slide&#39;s animations play on the canvas. The button is unavailable until the slide has at least one animation.</p><h2 id="effects" tabindex="-1">Effects <a class="header-anchor" href="#effects" aria-label="Permalink to &quot;Effects&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Category</th><th>Effects</th></tr></thead><tbody><tr><td>Entrance</td><td>Appear, Fade In, Fly In, Zoom In, Spin</td></tr><tr><td>Exit</td><td>Disappear, Fade Out, Fly Out, Zoom Out</td></tr><tr><td>Emphasis</td><td>Pulse, Grow</td></tr></tbody></table><p><strong>Easing</strong> options are <strong>Linear</strong>, <strong>Ease In</strong>, <strong>Ease Out</strong>, and <strong>Ease In Out</strong>. <strong>Duration</strong> ranges from 100 to 3,000 milliseconds.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>If your computer or browser is set to reduce motion, transitions become instant cuts and animated objects appear in their final state.</li><li>A transition&#39;s speed has three presets. You can&#39;t type a custom length.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/slides/present.html">Present</a> to play the deck with its transitions and animations.</li><li><a href="/docs/slides/style-and-arrange.html">Style and arrange</a> to group objects so they animate together.</li><li><a href="/docs/slides/keyboard-shortcuts.html">Keyboard shortcuts</a> for moving through a slideshow.</li></ul>',24)])])}const u=n(s,[["render",r]]);export{p as __pageData,u as default};
